    /// <summary>A room inside (x0, y0)..(x1, y1) walled on its edges, with an edge door in the middle of its south side.</summary>
    public static List<ScenarioEdgesItem> box(int x0, int y0, int x1, int y1)
    {
        List<ScenarioEdgesItem> edges = [];
        /*TODO return type*/object add(double x, double y, string side, string kind = "wall")
        {
            return edges.push(new() { x = Js.I(x), y = Js.I(y), side = side, kind = kind });
        }
        var doorX = JsMath.floor(((double)((x0 + x1)) / (2)));
        for (var x = x0; x <= x1; x++)
        {
            add(x, y0, "n");
            add(x, y1 + 1, "n", (x == doorX) ? "door" : "wall");
        }
        for (var y = y0; y <= y1; y++)
        {
            add(x0, y, "w");
            add(x1 + 1, y, "w");
        }
        return edges;
    }
    public static List<ScenarioEdgesItem> box(double x0, double y0, double x1, double y1) => box((int)x0, (int)y0, (int)x1, (int)y1);

    public static readonly List<string> MAP = [".......", ".......", ".......", ".......", ".......", ".......", "......."];

    /// <summary>walls on tile edges</summary>
    public class D001_walls_on_tile_edges
    {

        [Fact(DisplayName = "walls on tile edges > paths go round an edge wall and in through the edge door")]
        public void T002_paths_go_round_an_edge_wall_and_in_through_the_edge_door()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP, edges = box(1, 1, 3, 3) });
            var path = Js.NN(Pathfinding.findPath(state.grid, new Point { x = Js.I(1), y = Js.I(1) }, new Point { x = Js.I(0), y = Js.I(1) }));
            expect(path.some((p) => (p.x == 2) && (p.y == 4))).toBe(true);
            expect(path.length).toBeGreaterThan(4);
            expect(Pathfinding.canReach(state.grid, state.walkabilityVersion, new Point { x = Js.I(0), y = Js.I(0) }, new List<Point> { new Point { x = Js.I(2), y = Js.I(2) } }, "zombie")).toBe(false);
            state.grid.edgeOpen.push(Grids.edgeBetween(state.grid, 2, 3, 2, 4));
            state.walkabilityVersion++;
            expect(Pathfinding.canReach(state.grid, state.walkabilityVersion, new Point { x = Js.I(0), y = Js.I(0) }, new List<Point> { new Point { x = Js.I(2), y = Js.I(2) } }, "zombie")).toBe(true);
        }

        [Fact(DisplayName = "walls on tile edges > an edge-walled room is a room, its edge door its door")]
        public void T003_an_edge_walled_room_is_a_room_its_edge_door_its_door()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP, edges = box(1, 1, 3, 3) });
            var map = Rooms.getRoomMap(state);
            var room = Js.NN(map.rooms.find((r) => r.tiles.includes((2 * 7) + 2)));
            expect(room).toBeDefined();
            expect(room.tiles).toHaveLength(9);
            expect(room.doors).toHaveLength(1);
        }

        [Fact(DisplayName = "walls on tile edges > a body can't overlap an edge wall: you slide along it")]
        public void T004_a_body_can_t_overlap_an_edge_wall_you_slide_along_it()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP, edges = box(1, 1, 3, 3) });
            var inside = Motion.centre(new Point { x = Js.I(1), y = Js.I(2) });
            expect(Motion.fits(state.grid, inside, "free")).toBe(true);
            var moved = Motion.slide(state.grid, inside, -Motion.SUB, 0, "free");
            expect(moved.x).toBeGreaterThanOrEqual((1 * Motion.SUB) + 77);
            expect(Motion.fits(state.grid, new Point { x = Js.I(1 * Motion.SUB), y = Js.I(inside.y) }, "free")).toBe(false);
        }

        [Fact(DisplayName = "walls on tile edges > a colonist opens the edge door going through, and it shuts behind them")]
        public void T005_a_colonist_opens_the_edge_door_going_through_and_it_shuts_be()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP.map((r, y) => (y == 2) ? "..s...." : r), edges = box(1, 1, 3, 3) });
            var s = Js.NN(Js.Get(state.survivors, 0));
            foreach (var k in Js.Iter(Js.ObjectKeys(s.priorities)))
            {
                s.priorities[Js.Idx(k)] = 0;
            }
            var door = Grids.edgeBetween(state.grid, 2, 3, 2, 4);
            expect(Js.Get(state.grid.edges, door)).toBe(Grids.EDGE_DOOR);
            Commands.applyCommand(state, new Command { type = "moveSurvivor", survivorId = s.id, x = Js.I(2), y = Js.I(6) });
            var wasOpen = false;
            for (var t = 0; t < 60; t++)
            {
                Tick.tick(state);
                if (Grids.edgeIsOpen(state.grid, door))
                {
                    wasOpen = true;
                }
            }
            expect(s.pos).toEqual(Js.Obj(("x", (object?)(2)), ("y", (object?)(6))));
            expect(wasOpen).toBe(true);
            expect(Grids.edgeIsOpen(state.grid, door)).toBe(false);
        }

        [Fact(DisplayName = "walls on tile edges > you open and shut an edge door by using the tile across it")]
        public void T006_you_open_and_shut_an_edge_door_by_using_the_tile_across_it()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP.map((r, y) => (y == 3) ? "..s...." : r), edges = box(1, 1, 3, 3) });
            var s = Js.NN(Js.Get(state.survivors, 0));
            Commands.applyCommand(state, new Command { type = "takeControl", survivorId = s.id });
            var door = Grids.edgeBetween(state.grid, 2, 3, 2, 4);
            expect(Commands.applyCommand(state, new Command { type = "use", x = Js.I(2), y = Js.I(4) }).ok).toBe(true);
            expect(Grids.edgeIsOpen(state.grid, door)).toBe(true);
            expect(Commands.applyCommand(state, new Command { type = "use", x = Js.I(2), y = Js.I(4) }).ok).toBe(true);
            expect(Grids.edgeIsOpen(state.grid, door)).toBe(false);
        }

