        [Fact(DisplayName = "walls on tile edges > edges survive a save and load")]
        public void T008_edges_survive_a_save_and_load()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP, edges = box(1, 1, 3, 3) });
