        [Fact(DisplayName = "walls on tile edges > the dead batter an edge door down to get at someone inside")]
        public void T009_the_dead_batter_an_edge_door_down_to_get_at_someone_inside()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP.map((r, y) => (y == 2) ? "..s...." : ((y == 6) ? "..z...." : r)), edges = box(1, 1, 3, 3) });
            var s = Js.NN(Js.Get(state.survivors, 0));
            foreach (var k in Js.Iter(Js.ObjectKeys(s.priorities)))
            {
                s.priorities[Js.Idx(k)] = 0;
            }
            Js.NN(Js.Get(state.zombies, 0)).kind = "static";
            Js.NN(Js.Get(state.zombies, 0)).targetId = s.id;
            var door = Grids.edgeBetween(state.grid, 2, 3, 2, 4);
            var broke = false;
            for (var t = 0; (t < 400) && !broke; t++)
            {
                Tick.tick(state);
                broke = Js.Get(state.grid.edges, door) != Grids.EDGE_DOOR;
            }
            expect(broke).toBe(true);
            expect(state.events.some((e) => e.message.includes("broke through the door"))).toBe(true);
        }

        [Fact(DisplayName = "walls on tile edges > a colonist mends a damaged edge wall from either side")]
        public void T010_a_colonist_mends_a_damaged_edge_wall_from_either_side()
        {
