        [Fact(DisplayName = "walls on tile edges > nobody bites or hits through an edge wall")]
        public void T012_nobody_bites_or_hits_through_an_edge_wall()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP.map((r, y) => (y == 2) ? "...sz.." : r), edges = box(1, 1, 3, 3) });
            var s = Js.NN(Js.Get(state.survivors, 0));
