        [Fact(DisplayName = "walls on tile edges > an edge barricade keeps the dead out but not you or the colonists")]
        public void T013_an_edge_barricade_keeps_the_dead_out_but_not_you_or_the_colo()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP, edges = [new() { x = Js.I(2), y = Js.I(2), side = "w", kind = "wall" }] });
            Commands.applyCommand(state, new Command { type = "designateBuild", x = Js.I(3), y = Js.I(3), structure = "barricade", side = "w" });
            var bp = Js.NN(Js.Get(state.blueprints, 0));
            bp.delivered = true;
            bp.workDone = bp.workRequired;
            Designations.completeBlueprint(state, bp);
            expect(Pathfinding.crossable(state.grid, 2, 3, 3, 3, "zombie")).toBe(false);
            expect(Pathfinding.crossable(state.grid, 2, 3, 3, 3, "survivor")).toBe(true);
            expect(Pathfinding.crossable(state.grid, 2, 3, 3, 3, "free")).toBe(true);
        }

        [Fact(DisplayName = "walls on tile edges > a locked edge door: raiders cannot open it, colonists have keys")]
        public void T014_a_locked_edge_door_raiders_cannot_open_it_colonists_have_key()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = MAP, edges = box(1, 1, 3, 3) });
            expect(Commands.applyCommand(state, new Command { type = "toggleLock", x = Js.I(2), y = Js.I(4), side = "n" }).ok).toBe(true);
            expect(Pathfinding.crossable(state.grid, 2, 4, 2, 3, "raider")).toBe(false);
            expect(Pathfinding.crossable(state.grid, 2, 4, 2, 3, "survivor")).toBe(true);
            Commands.applyCommand(state, new Command { type = "toggleLock", x = Js.I(2), y = Js.I(4), side = "n" });
            expect(Pathfinding.crossable(state.grid, 2, 4, 2, 3, "raider")).toBe(true);
        }
